import importlib.util
import inspect
import json
from pathlib import Path
import random
import statistics
import time
import timeit

from unstd.crypto import token

root = Path(__file__).parent
spec = importlib.util.spec_from_file_location('token_original_baseline', '/tmp/unstd-token-baseline-20261022.py')
baseline = importlib.util.module_from_spec(spec)
spec.loader.exec_module(baseline)
source = inspect.getsource(token._verify_python)
start = source.index('    if max_token_chars is not None:')
end = source.index('    if type(token) is str:', start)
configs = {
    'identity_chain': '''    if max_token_chars is _DEFAULT_MAX_TOKEN_CHARS:
        if not _MIN_TOKEN_CHARS <= _str_len(token) <= _DEFAULT_MAX_TOKEN_CHARS:
            return None
    elif max_token_chars is not None:
        if type(max_token_chars) is not int:
            msg = "max_token_chars must be a positive integer or None"
            raise TypeError(msg)
        if max_token_chars <= 0:
            msg = "max_token_chars must be a positive integer or None"
            raise ValueError(msg)
        if not _MIN_TOKEN_CHARS <= _str_len(token) <= max_token_chars:
            return None
''',
    'identity_local': '''    if max_token_chars is _DEFAULT_MAX_TOKEN_CHARS:
        token_chars = _str_len(token)
        if token_chars < _MIN_TOKEN_CHARS or token_chars > _DEFAULT_MAX_TOKEN_CHARS:
            return None
    elif max_token_chars is not None:
        if type(max_token_chars) is not int:
            msg = "max_token_chars must be a positive integer or None"
            raise TypeError(msg)
        if max_token_chars <= 0:
            msg = "max_token_chars must be a positive integer or None"
            raise ValueError(msg)
        token_chars = _str_len(token)
        if token_chars < _MIN_TOKEN_CHARS or token_chars > max_token_chars:
            return None
''',
    'identity_inline': '''    if max_token_chars is _DEFAULT_MAX_TOKEN_CHARS:
        if not 46 <= _str_len(token) <= 8192:
            return None
    elif max_token_chars is not None:
        if type(max_token_chars) is not int:
            msg = "max_token_chars must be a positive integer or None"
            raise TypeError(msg)
        if max_token_chars <= 0:
            msg = "max_token_chars must be a positive integer or None"
            raise ValueError(msg)
        if not _MIN_TOKEN_CHARS <= _str_len(token) <= max_token_chars:
            return None
''',
}
functions = {'baseline': baseline.verify, 'current': token._verify_python}
for name, block in configs.items():
    candidate_source = source[:start] + block + source[end:]
    path = root / f'python-{name}.py'
    path.write_text(candidate_source)
    namespace = dict(token.__dict__)
    exec(compile(candidate_source, str(path), 'exec'), namespace)
    functions[name] = namespace['verify']

key = bytes(range(32))
good = token.mint(key, b'{"sub":"u1"}')
cases = {'empty': '', 'no_separator': 'malformed', 'extra_dot': good + '.extra',
         'valid': good, 'wrong_key': good, 'over_limit': 'A' * 8193}
samples = {name: {case: [] for case in cases} for name in functions}
timers = {(name, case): timeit.Timer('verify(key, bearer)', globals={
    'verify': function, 'key': key[::-1] if case == 'wrong_key' else key, 'bearer': bearer}, timer=time.process_time_ns)
    for name,function in functions.items() for case,bearer in cases.items()}
# Calibrate once against the original rather than changing batch counts per
# candidate. Pair interleaved rounds, retaining every per-call CPU sample.
counts = {}
for case in cases:
    elapsed = timers['current', case].timeit(number=10000)
    counts[case] = max(1000, int(10_000_000 / (elapsed / 10000)))
rng = random.Random(321)
for round_number in range(17):
    order = [(name,case) for case in cases for name in functions]
    rng.shuffle(order)
    for name,case in order:
        count = counts[case]
        samples[name][case].append(timers[name,case].timeit(number=count) / count)
report = {'rounds':17, 'target_cpu_ns_per_sample':10_000_000, 'samples_ns':samples, 'summary':{}}
for name in functions:
    report['summary'][name] = {}
    for case in cases:
        median = statistics.median(samples[name][case])
        ratios = [left/right for left,right in zip(samples['baseline'][case], samples[name][case])]
        report['summary'][name][case] = {'median_ns': median,'baseline_ratio': statistics.median(ratios)}
(root/'python-micro-results.json').write_text(json.dumps(report,indent=2)+'\n')
print(json.dumps(report['summary'],indent=2))

import importlib.util
import inspect
import json
from pathlib import Path
import random
import statistics
import time
import timeit

from unstd.crypto import token

root = Path(__file__).parent
spec = importlib.util.spec_from_file_location('token_original_baseline', '/tmp/unstd-token-baseline-20261022.py')
baseline = importlib.util.module_from_spec(spec)
spec.loader.exec_module(baseline)
source = inspect.getsource(token._verify_python)
start = source.index('    if max_token_chars is not None:')
end = source.index('    # Unpadded Base64', start)
old = source[start:end]
variants = {}
fast = '''    if max_token_chars is _DEFAULT_MAX_TOKEN_CHARS and type(token) is str:
        token_chars = len(token)
        if token_chars < _MIN_TOKEN_CHARS or token_chars > _DEFAULT_MAX_TOKEN_CHARS:
            return None
        if token[-44] != SEPARATOR:
            return None
        payload = token[:-44]
        tag = token[-43:]
    else:
'''
variants['exact_default'] = fast + ''.join('    ' + line if line.strip() else line for line in old.splitlines(keepends=True))
variants['exact_default_chain'] = variants['exact_default'].replace(
    '        token_chars = len(token)\n        if token_chars < _MIN_TOKEN_CHARS or token_chars > _DEFAULT_MAX_TOKEN_CHARS:',
    '        if not _MIN_TOKEN_CHARS <= len(token) <= _DEFAULT_MAX_TOKEN_CHARS:')
variants['exact_bool'] = ('    is_plain = type(token) is str\n' + old
    .replace('token_chars = _str_len(token)', 'token_chars = len(token) if is_plain else _str_len(token)')
    .replace('if type(token) is str:', 'if is_plain:'))
functions = {'baseline':baseline.verify, 'current':token._verify_python}
for name, block in variants.items():
    candidate = source[:start] + block + source[end:]
    path = root / f'python-{name}.py'
    path.write_text(candidate)
    namespace = dict(token.__dict__)
    exec(compile(candidate,str(path),'exec'),namespace)
    functions[name]=namespace['verify']

key=bytes(range(32))
good=token.mint(key,b'x'*42)
cases={'empty':'','no_separator':'junk','extra_dot':good+'.extra','valid':good,'wrong_key':good}
# Check request/config behavior before timing candidates.
def outcome(function, key, bearer, limit):
    try:return ('return',function(key,bearer,max_token_chars=limit))
    except BaseException as error:return ('raise',type(error),str(error))
randomizer=random.Random(123)
alphabet='ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_./= \x00é😀\ud800'
inputs=list(cases.values())+['A'*8193,'é'*8193,'😀'*8193]
for _ in range(300):
    value=list(good)
    value[randomizer.randrange(len(value))]=randomizer.choice(alphabet)
    inputs.append(''.join(value))
for name,function in functions.items():
    if name in ('baseline','current'):continue
    for bearer in inputs:
        for key_variant in (key,b'',key[::-1]):
            for limit in (8192,None,1,True,8192.0,0,-1,1<<10000,-(1<<10000)):
                assert outcome(function,key_variant,bearer,limit)==outcome(token._verify_python,key_variant,bearer,limit),(name,bearer,limit)
samples={name:{case:[] for case in cases} for name in functions}
timers={(name,case):timeit.Timer('verify(key, bearer)',globals={'verify':function,'key':key[::-1] if case=='wrong_key' else key,'bearer':bearer},timer=time.process_time_ns)
        for name,function in functions.items() for case,bearer in cases.items()}
counts={}
for case in cases:
    elapsed=timers['current',case].timeit(number=10000)
    counts[case]=max(1000,int(10_000_000/(elapsed/10000)))
for at in range(19):
    order=[(name,case) for case in cases for name in functions]
    randomizer.shuffle(order)
    for name,case in order:
        samples[name][case].append(timers[name,case].timeit(number=counts[case])/counts[case])
summary={name:{case:{'median_ns':statistics.median(samples[name][case]),'baseline_ratio':statistics.median([left/right for left,right in zip(samples['baseline'][case],samples[name][case])])} for case in cases} for name in functions}
(root/'python-fast-micro-results.json').write_text(json.dumps({'rounds':19,'samples_ns':samples,'summary':summary,'differential_cases_per_candidate':len(inputs)*27},indent=2)+'\n')
print(json.dumps(summary,indent=2))
